import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import io from 'socket.io-client';
import './App.css';

// Server URL - This will be proxied through the React proxy configuration
const SERVER_URL = '/api';
const SOCKET_URL = ''; // Empty string for relative URL

// Placeholder Google logo image (base64 encoded small Google logo)
const PLACEHOLDER_IMAGE = 'data:image/png;base64,';

// At the top of the file, add a constant for timeouts
const RESPONSE_TIMEOUT = 20000; // 20 seconds timeout for responses
const MAX_LOADING_TIME = 30000; // 30 seconds max loading time before forcing exit

// Message component to render individual chat messages
const Message = ({ message, isLoading }) => {
    const roleClass = `message ${message.role}${isLoading ? ' loading' : ''}`;

    // Render different content based on message role
    const renderContent = () => {
        if (message.role === 'tool' || message.tool_call_id) {
            // Tool message rendering
            return (
                <pre className="tool-content">
                    {typeof message.content === 'string'
                        ? message.content
                        : JSON.stringify(message.content, null, 2)}
                </pre>
            );
        } else if (message.tool_calls) {
            // Message with tool calls
            return (
                <>
                    <div className="message-text">{message.content}</div>
                    <div className="tool-calls">
                        {message.tool_calls.map((tool, idx) => (
                            <div key={idx} className="tool-call">
                                <div className="tool-name">{tool.function?.name || 'Unknown Tool'}</div>
                                <pre className="tool-args">{tool.function?.arguments || '{}'}</pre>
                            </div>
                        ))}
                    </div>
                </>
            );
        } else {
            // Standard text message
            return <div className="message-text">{message.content}</div>;
        }
    };

    return (
        <div className={roleClass}>
            <div className="message-header">{message.role}</div>
            <div className="message-content">
                {isLoading ? (
                    <>
                        {message.content && <div className="message-text">{message.content}</div>}
                        <div className="loading-indicator">...</div>
                    </>
                ) : (
                    renderContent()
                )}
            </div>
        </div>
    );
};

function App() {
    const [sessionId, setSessionId] = useState(null);
    const [inputValue, setInputValue] = useState('');
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [browserImage, setBrowserImage] = useState(PLACEHOLDER_IMAGE); // Set initial placeholder image
    const [previewVisible, setPreviewVisible] = useState(true);
    // Add state for status messages
    const [statusMessages, setStatusMessages] = useState([{
        type: 'info',
        text: 'Test starting...',
        time: new Date().toLocaleTimeString()
    }]);
    // Add state for streaming
    const [streaming, setStreaming] = useState(false);
    const [streamStatus, setStreamStatus] = useState('waiting');
    const eventSourceRef = useRef(null);
    const messagesEndRef = useRef(null);
    // Add state for showing technical messages
    const [showTechnicalMessages, setShowTechnicalMessages] = useState(true);
    const [socket, setSocket] = useState(null);

    // Toggle display of technical messages
    const toggleTechnicalMessages = () => {
        setShowTechnicalMessages(!showTechnicalMessages);
    };

    // Helper function to add status messages with a timestamp
    const addStatusMessage = (type, text) => {
        const now = new Date();
        const timeString = now.toLocaleTimeString();
        setStatusMessages(prev => {
            // Keep only the most recent 10 messages
            const newMessages = [...prev, { type, text, time: timeString }];
            if (newMessages.length > 10) {
                return newMessages.slice(newMessages.length - 10);
            }
            return newMessages;
        });
    };

    // Helper to determine status type classes
    const getStatusType = (event) => {
        switch (event) {
            case 'error': return 'error';
            case 'thinking': return 'processing';
            case 'user-message': return 'user';
            case 'ai-response': return 'assistant';
            case 'tool-call': return 'tool';
            case 'response-complete': return 'success';
            case 'warning': return 'warning';
            case 'reconnecting': return 'reconnecting';
            default: return 'info';
        }
    };

    // Replace the existing fetchMessagesDirectly function with a simpler version
    const fetchMessagesDirectly = useCallback(() => {
        if (!sessionId) return;

        console.log('Fetching messages directly via API...');
        addStatusMessage('system', 'Fetching messages from server...');

        axios.get(`/api/messages/${sessionId}?_t=${Date.now()}`)
            .then(response => {
                if (response.data.success && response.data.messages) {
                    // Update messages in state
                    setMessages(response.data.messages);

                    // Check if we have any assistant messages
                    const hasAssistantMessage = response.data.messages.some(m =>
                        m.role === 'assistant' && m.content && m.content.length > 0);

                    if (hasAssistantMessage) {
                        // If we have an assistant message, exit loading state
                        setLoading(false);
                        addStatusMessage('success', 'Response received');
                    } else {
                        addStatusMessage('warning', 'No assistant response found');
                    }
                } else {
                    addStatusMessage('warning', 'API returned no messages');
                }
            })
            .catch(err => {
                console.error('Error fetching messages:', err);
                addStatusMessage('error', `Failed to fetch messages: ${err.message}`);
            });
    }, [sessionId, addStatusMessage]);

    // Initialize session when component mounts
    useEffect(() => {
        const initSession = async () => {
            try {
                console.log("Initializing session...");
                const response = await axios.post('/api/session');
                if (response.data.success) {
                    const newSessionId = response.data.sessionId;
                    setSessionId(newSessionId);
                    console.log(`Session initialized: ${newSessionId}`);

                    // Join the session room using Socket.IO
                    const socket = io.connect();
                    socket.emit('join-session', newSessionId);

                    addStatusMessage('system', `Session initialized: ${newSessionId}`);

                    // Initialize tools
                    await axios.get('/api/init')
                        .then(res => {
                            console.log("Tools initialized:", res.data);
                            if (res.data.toolCount) {
                                addStatusMessage('system', `Initialized ${res.data.toolCount} tools`);
                            }
                        })
                        .catch(err => {
                            console.error("Error initializing tools:", err);
                            addStatusMessage('error', `Error initializing tools: ${err.message}`);
                        });

                    // Take an initial screenshot
                    await requestScreenshot();

                    // Automatically start streaming after a short delay to allow screenshot to complete
                    setTimeout(() => {
                        addStatusMessage('info', 'Auto-starting browser stream...');
                        startStream();
                    }, 1500);
                } else {
                    setError(`Error initializing session: ${response.data.error}`);
                }
            } catch (err) {
                console.error("Session initialization error:", err);
                setError(`Failed to initialize session: ${err.message}`);
            }
        };

        initSession();
    }, []);

    // Socket connection
    useEffect(() => {
        let socket;

        const connectSocket = () => {
            console.log("Connecting to socket...");
            socket = io({
                reconnectionAttempts: Infinity, // Try to reconnect forever
                reconnectionDelay: 1000,
                reconnectionDelayMax: 5000, // Cap the delay at 5 seconds
                timeout: 20000, // Increase timeout to 20 seconds
                transports: ['websocket', 'polling'], // Try WebSocket first, fall back to polling
                forceNew: true,
                upgrade: true,
                rememberUpgrade: true,
                path: '/socket.io/',
                extraHeaders: {
                    'Accept': 'application/json, text/plain, */*',
                    'User-Agent': 'Browser Client'
                }
            });

            socket.on('connect', () => {
                console.log('Socket connected!', socket.id);
                // Add a status message when connected
                addStatusMessage('system', `Connected to server (${socket.id})`);

                // Join session room if we have a sessionId
                if (sessionId) {
                    console.log(`Joining session room: ${sessionId}`);
                    socket.emit('join-session', sessionId);
                }
            });

            socket.on('session-joined', (data) => {
                console.log('Joined session room:', data);
                addStatusMessage('system', `Joined session: ${data.sessionId}`);

                // When we successfully join a session, check for any missed messages
                // This ensures we have the latest state if reconnecting
                if (loading) {
                    fetchMessagesDirectly();
                }
            });

            socket.on('connect_error', (error) => {
                console.error('Socket connection error:', error);
                addStatusMessage('error', `Connection error: ${error.message}`);
            });

            socket.on('reconnect_attempt', (attemptNumber) => {
                console.log(`Attempting to reconnect (${attemptNumber})...`);
                addStatusMessage('system', `Reconnecting (attempt ${attemptNumber})...`);
            });

            socket.on('reconnect', (attemptNumber) => {
                console.log(`Successfully reconnected after ${attemptNumber} attempts`);
                addStatusMessage('success', `Reconnected to server`);

                // Re-join session room after reconnection
                if (sessionId) {
                    console.log(`Re-joining session after reconnect: ${sessionId}`);
                    socket.emit('join-session', sessionId);
                }
            });

            // Handler for incremental message updates - NEW EVENT
            socket.on('message-update', (data) => {
                console.log('Incremental message update received:', data);

                if (data.sessionId === sessionId && data.message) {
                    console.log('Processing incremental update');

                    // Update the message state with the new message
                    setMessages(prevMessages => {
                        // Find if there's an existing message to update
                        const existingIndex = prevMessages.findIndex(m =>
                            m.role === data.message.role &&
                            (m.id === data.message.id || (!m.id && !data.message.id))
                        );

                        if (existingIndex >= 0) {
                            // Update existing message
                            const updatedMessages = [...prevMessages];
                            updatedMessages[existingIndex] = data.message;
                            return updatedMessages;
                        } else {
                            // Add new message
                            return [...prevMessages, data.message];
                        }
                    });

                    // If message update is marked as complete, exit loading state
                    if (data.isComplete) {
                        setLoading(false);
                        addStatusMessage('success', 'Response complete');
                    }
                }
            });

            // Handler for processing updates
            socket.on('processing-update', (data) => {
                console.log('Processing update:', data);
                addStatusMessage('processing', data.message || 'Processing...');
                setLoading(true);

                // If the processing update includes a tool call, display it in messages
                if (data.toolCall) {
                    setMessages(prevMessages => {
                        const toolMessage = {
                            role: 'system',
                            content: `Using tool: ${data.toolCall.name || 'unknown'}`
                        };
                        return [...prevMessages, toolMessage];
                    });
                }
            });

            // Handler for chat responses - SIMPLIFIED TO PREVENT GETTING STUCK
            socket.on('chat-response', (data) => {
                console.log('Chat response received via WebSocket:', data);
                if (data.success && data.messages) {
                    // Update the messages state
                    setMessages(data.messages);

                    // Check if this is a complete response
                    if (data.isComplete !== false) {
                        setLoading(false);
                        addStatusMessage('success', 'Response complete');
                    } else {
                        // Still leave a timeout to prevent getting stuck
                        addStatusMessage('info', 'Received partial response, still processing...');
                    }

                    // Automatically stop the stream when the assistant is done responding
                    if (data.isComplete && streaming) {
                        addStatusMessage('info', 'Assistant finished - stopping stream');
                        setTimeout(() => {
                            stopStream();
                        }, 2000); // Give a short delay to allow the final screenshot to be displayed
                    }
                }
            });

            // Handler for chat errors
            socket.on('chat-error', (data) => {
                console.error('Chat error received via WebSocket:', data);
                // Always exit loading state on error
                setLoading(false);
                setError(data.error || 'Unknown error during processing');
                addStatusMessage('error', `Error: ${data.error || 'Unknown error'}`);
            });

            // Add listener for status updates from the server
            socket.on('status-update', (data) => {
                console.log('Status update:', data);
                addStatusMessage(getStatusType(data.event), data.message);
            });

            // Add listener for stream status updates
            socket.on('stream-status', (data) => {
                console.log('Stream status update:', data);
                addStatusMessage(
                    data.status === 'error' ? 'error' : 'stream',
                    data.message || `Stream ${data.status}`
                );
                // Update stream status state
                setStreamStatus(data.status);
            });

            // Add listener for assistant complete signal
            socket.on('assistant-complete', (data) => {
                console.log('Assistant complete signal received:', data);
                addStatusMessage('success', data.message || 'Assistant processing complete');

                // If we haven't received the messages yet, fetch them directly
                const hasCompleteAssistantResponse = messages.some(m =>
                    m.role === 'assistant' &&
                    (
                        // Consider using our better detection method
                        (m.content && !m.content.includes("I'm sorry, I encountered an error")) ||
                        (m.finish_reason === 'stop' || m.finish_reason === 'tool_calls')
                    )
                );

                if (!hasCompleteAssistantResponse || loading) {
                    addStatusMessage('system', 'Fetching final results directly...');
                    fetchMessagesDirectly();
                }

                // Stop the stream if it's running
                if (streaming) {
                    addStatusMessage('info', data.message || 'Assistant finished - stopping stream');
                    setTimeout(() => {
                        stopStream();
                    }, 1500); // Small delay to ensure final screenshot is received
                }
            });

            // Add listener for broadcast events that might be sent to all clients
            socket.on('chat-broadcast', (data) => {
                console.log('Broadcast message received:', data);

                if (data.sessionId === sessionId) {
                    // This broadcast is for our session
                    addStatusMessage('info', `Got message update: ${data.messageCount} messages (has assistant response: ${data.hasAssistantResponse})`);

                    // If we don't get a direct chat-response soon, request the messages
                    if (data.hasAssistantResponse) {
                        // Check if we already have assistant messages using improved detection
                        const messagesWithAssistantResponse = messages.filter(m => m.role === 'assistant');
                        const hasCompleteAssistantResponse = messagesWithAssistantResponse.length > 0 &&
                            isResponseComplete(messages, messagesWithAssistantResponse);

                        // If we already have messages, no need to fetch
                        if (hasCompleteAssistantResponse) {
                            console.log('Already have complete assistant messages, no need to fetch');
                            if (loading) setLoading(false);
                            return;
                        }

                        // Try multiple times with increasing delays to ensure we get the messages
                        let retryAttempt = 0;
                        const MAX_RETRIES = 3;
                        const retry = () => {
                            retryAttempt++;
                            // Check again if we've received messages before making API call
                            const messagesWithAssistantResponse = messages.filter(m => m.role === 'assistant');
                            const hasCompleteAssistantResponse = messagesWithAssistantResponse.length > 0 &&
                                isResponseComplete(messages, messagesWithAssistantResponse);

                            if (!hasCompleteAssistantResponse && retryAttempt <= MAX_RETRIES) {
                                addStatusMessage('system', `Requesting messages from server (attempt ${retryAttempt}/${MAX_RETRIES})...`);
                                fetchMessagesDirectly();

                                // Schedule next retry with exponential backoff
                                if (retryAttempt < MAX_RETRIES) {
                                    setTimeout(retry, 2000 * Math.pow(2, retryAttempt - 1));
                                }
                            }
                        };

                        // Start first attempt after short delay
                        setTimeout(retry, 2000);
                    }
                }
            });

            socket.on('error', (error) => {
                console.error('Socket error:', error);
                addStatusMessage('error', `Socket error: ${error}`);

                // If we're still loading, try to fetch messages directly after a socket error
                if (loading && sessionId) {
                    setTimeout(() => {
                        fetchMessagesDirectly();
                    }, 1000);
                }
            });

            // Add reconnect_failed handler for better error recovery
            socket.on('reconnect_failed', () => {
                console.error('Socket reconnection failed');
                addStatusMessage('error', 'Connection failed. Trying alternative methods...');

                // If socket reconnection fails, try to fetch messages directly
                if (sessionId) {
                    fetchMessagesDirectly();
                }
            });

            socket.on('disconnect', (reason) => {
                console.log(`Socket disconnected: ${reason}`);
                addStatusMessage('system', `Disconnected: ${reason}`);

                // If we're still loading when a disconnect happens, try fetching messages directly
                if (loading && sessionId) {
                    setTimeout(() => {
                        fetchMessagesDirectly();
                    }, 2000);
                }
            });
        };

        connectSocket();

        // Setup a health check ping to keep the connection alive
        const healthCheckInterval = setInterval(() => {
            if (socket && socket.connected) {
                // Send a health check ping
                socket.emit('health-check', { timestamp: Date.now() });
            } else if (socket) {
                // If socket exists but isn't connected, try to reconnect
                console.log('Socket disconnected during health check, reconnecting...');
                socket.connect();
            }
        }, 30000); // Every 30 seconds

        return () => {
            clearInterval(healthCheckInterval);
            if (socket) {
                socket.disconnect();
            }
        };
    }, [sessionId, messages]);

    // Simplify the loading timeout logic - replace the existing fallback mechanism with this
    useEffect(() => {
        let loadingTimer = null;

        if (loading && sessionId) {
            // Set a single timer to auto-fetch messages after a delay
            loadingTimer = setTimeout(() => {
                console.log('Auto-fetching messages after timeout');
                fetchMessagesDirectly();
            }, RESPONSE_TIMEOUT);

            // Set a second timer to force exit loading state if it's been too long
            const forceResetTimer = setTimeout(() => {
                console.log('Forcing exit from loading state after maximum time');
                setLoading(false);
                addStatusMessage('warning', 'Response timed out. Try sending another message.');
            }, MAX_LOADING_TIME);

            // Store both timers for cleanup
            return () => {
                clearTimeout(loadingTimer);
                clearTimeout(forceResetTimer);
            };
        }

        return () => {
            if (loadingTimer) clearTimeout(loadingTimer);
        };
    }, [loading, sessionId, fetchMessagesDirectly, addStatusMessage]);

    // Add a function to check server health and forcibly reset the UI if needed
    const forceCancelResponse = useCallback(() => {
        console.log('Manually cancelling response...');

        // Clear any pending fallback timers
        if (window._fallbackTimers) {
            window._fallbackTimers.forEach(timer => clearTimeout(timer));
            window._fallbackTimers = [];
        }

        // Reset loading state
        setLoading(false);
        addStatusMessage('warning', 'Response cancelled by user');

        // Close any active connections
        try {
            const socket = io.connect();
            socket.emit('cancel-processing', { sessionId });
            setTimeout(() => socket.disconnect(), 1000);
        } catch (err) {
            console.error('Error during cleanup:', err);
        }
    }, [sessionId, addStatusMessage]);

    // Add a function to check server health
    const checkServerHealth = () => {
        console.log('Checking server health...');
        addStatusMessage('system', 'Checking server connection...');

        // Check the Deno server first
        axios.get('/api/ping', { timeout: 5000 })
            .then(response => {
                if (response.data === 'pong') {
                    addStatusMessage('success', 'Server is responsive!');

                    // Now check session health
                    return axios.get(`/api/session/${sessionId}/check`, { timeout: 5000 });
                } else {
                    addStatusMessage('error', 'Server returned unexpected response');
                    return Promise.reject('Invalid server response');
                }
            })
            .then(response => {
                if (response.data.valid) {
                    addStatusMessage('success', 'Session is valid and active');
                } else {
                    addStatusMessage('warning', 'Session is invalid or expired');
                }
            })
            .catch(error => {
                console.error('Server check failed:', error);
                addStatusMessage('error', `Server check failed: ${error.message || 'Connection error'}`);
            });
    };

    // Start the browser stream
    const startStream = () => {
        if (eventSourceRef.current) {
            // If already streaming, stop first
            stopStream();
            // Wait a moment before reconnecting
            setTimeout(() => {
                initStream();
            }, 500);
            return;
        }

        initStream();
    };

    // Extracted stream initialization logic
    const initStream = () => {
        try {
            // Update UI state to show streaming is starting
            setStreaming(true);
            setStreamStatus('connecting');
            addStatusMessage('info', 'Test starting... Connecting to browser stream');

            // Create an EventSource for Server-Sent Events
            const streamId = sessionId || `stream-${Date.now()}`;

            // Add version and timestamp to prevent caching issues
            const version = Date.now();
            const streamUrl = `/api/browser-stream/${streamId}?_t=${version}`;

            console.log(`Creating EventSource with URL: ${streamUrl}`);

            // Try to create the EventSource
            try {
                eventSourceRef.current = new EventSource(streamUrl);

                // Add custom headers and options where possible
                if (eventSourceRef.current) {
                    // Set up event handlers - this creates the heartbeat and reconnection logic
                    setupStreamEventHandlers(streamUrl);

                    // Notify about connection attempt
                    addStatusMessage('stream', 'Connecting to test stream...');
                }
            } catch (connectionError) {
                console.error('EventSource connection error:', connectionError);
                addStatusMessage('error', `Stream connection failed: ${connectionError.message}`);
                setStreaming(false);
                setStreamStatus('error');
            }
        } catch (error) {
            console.error('Error starting stream:', error);
            addStatusMessage('error', `Error starting stream: ${error.message}`);
            setStreaming(false);
            setStreamStatus('error');
        }
    };

    // Set up event handlers for the stream
    const setupStreamEventHandlers = (streamUrl) => {
        if (!eventSourceRef.current) return;

        let reconnectTimer = null;
        let connectionTimeout = null;
        let reconnectAttempts = 0;
        const MAX_RECONNECT_ATTEMPTS = 5;
        const RECONNECT_DELAY = 3000; // 3 seconds

        // Function to handle reconnection
        const handleReconnect = (reason) => {
            if (reconnectTimer) clearTimeout(reconnectTimer);
            if (connectionTimeout) clearTimeout(connectionTimeout);

            // Stop the current stream
            stopStream();

            // Only try reconnecting if we haven't exceeded max attempts
            if (reconnectAttempts < MAX_RECONNECT_ATTEMPTS) {
                reconnectAttempts++;
                const delay = RECONNECT_DELAY * Math.min(reconnectAttempts, 3); // Exponential backoff, max 9 seconds

                // Use the reconnecting status for better UI feedback during reconnect attempts
                addStatusMessage('reconnecting', `Connection ${reason}. Reconnecting in ${delay / 1000} seconds... (Attempt ${reconnectAttempts}/${MAX_RECONNECT_ATTEMPTS})`);

                // If it's the first reconnect, just show connecting
                // For subsequent attempts, show a warning state
                if (reconnectAttempts === 1) {
                    setStreamStatus('connecting');
                } else {
                    setStreamStatus('warning');
                }

                reconnectTimer = setTimeout(() => {
                    // Only try to reconnect if we're not already connected
                    if (!eventSourceRef.current) {
                        addStatusMessage('reconnecting', `Attempting to reconnect... (Attempt ${reconnectAttempts}/${MAX_RECONNECT_ATTEMPTS})`);

                        try {
                            // Update pulsing state based on reconnection attempts
                            const streamStatusEl = document.querySelector('.stream-status');
                            if (streamStatusEl) {
                                // Add stronger pulsing for reconnection attempts
                                streamStatusEl.classList.add('pulsing');
                            }
                        } catch (uiError) {
                            console.warn('UI update error:', uiError);
                        }

                        // Try to start the stream again
                        startStream();
                    }
                }, delay);
            } else {
                // We've exceeded max reconnection attempts
                addStatusMessage('error', `Failed to reconnect after ${MAX_RECONNECT_ATTEMPTS} attempts. Please try manually reconnecting.`);
                setStreaming(false);
                setStreamStatus('error');
                reconnectAttempts = 0; // Reset for next manual attempt

                // Try once more after a longer delay (30 seconds)
                reconnectTimer = setTimeout(() => {
                    if (!eventSourceRef.current) {
                        addStatusMessage('reconnecting', 'Making one final reconnection attempt...');
                        startStream();
                    }
                }, 30000);
            }
        };

        // Handle connection open
        eventSourceRef.current.onopen = () => {
            console.log(`Stream connection opened: ${streamUrl}`);
            setStreaming(true);
            setStreamStatus('connected');
            addStatusMessage('success', 'Browser stream connected - Test is now running');

            // Reset reconnect attempts since we successfully connected
            reconnectAttempts = 0;

            // Clear any pending timeouts or intervals
            if (connectionTimeout) clearTimeout(connectionTimeout);
            if (reconnectTimer) clearTimeout(reconnectTimer);

            // Set a connection timeout in case we don't receive any messages
            connectionTimeout = setTimeout(() => {
                console.warn('No messages received in 15 seconds, reconnecting...');
                handleReconnect('timeout');
            }, 15000); // 15 seconds timeout
        };

        // Handle incoming messages
        eventSourceRef.current.onmessage = (event) => {
            // Reset connection timeout since we got a message
            if (connectionTimeout) {
                clearTimeout(connectionTimeout);
                connectionTimeout = setTimeout(() => {
                    console.warn('Connection idle timeout, reconnecting...');
                    handleReconnect('idle');
                }, 15000); // 15 seconds timeout
            }

            // Check if we have a valid event data
            if (!event || !event.data) {
                console.warn('Received empty message from stream');
                return;
            }

            // Process the incoming data
            try {
                // Store last received image in case we need to retry
                if (event.data.startsWith('data:image')) {
                    // Add timestamp/cache param if not already present to prevent browser caching
                    const imageUrl = event.data.includes('#t=') ?
                        event.data :
                        `${event.data}#t=${Date.now()}`;

                    setBrowserImage(imageUrl);
                }
            } catch (imageError) {
                console.error('Error processing image data:', imageError);
            }
        };

        // Handle errors
        eventSourceRef.current.onerror = (error) => {
            console.error('Stream error:', error);

            // Check if this is a browser installation issue
            const isBrowserIssue = checkForBrowserInstallationIssues('Stream connection failed');

            // If it's a browser installation issue, we don't want to keep retrying
            if (isBrowserIssue) {
                stopStream();
                setStreamStatus('error');
                addStatusMessage('error', 'Browser installation issue detected. See instructions above.');
                return;
            }

            // For other errors, try to reconnect
            handleReconnect('error');
        };

        // Handle status events
        eventSourceRef.current.addEventListener('status', (event) => {
            try {
                const statusData = JSON.parse(event.data);
                addStatusMessage(
                    statusData.type || 'stream',
                    statusData.message || `Stream ${statusData.type || 'event'}`
                );

                // Update UI status based on the event type
                if (statusData.type === 'connected') {
                    setStreamStatus('connected');
                    // Reset reconnect attempts
                    reconnectAttempts = 0;
                } else if (statusData.type === 'error') {
                    setStreamStatus('error');
                } else if (statusData.type === 'disconnected') {
                    setStreamStatus('disconnected');
                    stopStream();
                } else if (statusData.type === 'warning') {
                    // Don't change status for warnings, just log them
                }

                // Reset connection timeout since we got a status message
                if (connectionTimeout) {
                    clearTimeout(connectionTimeout);
                    connectionTimeout = setTimeout(() => {
                        console.warn('Connection idle timeout, reconnecting...');
                        handleReconnect('idle');
                    }, 15000); // 15 seconds idle timeout
                }
            } catch (parseError) {
                console.error('Error parsing status event:', parseError, event.data);
            }
        });

        // Create cleanup function for the effect
        return () => {
            if (connectionTimeout) clearTimeout(connectionTimeout);
            if (reconnectTimer) clearTimeout(reconnectTimer);
            stopStream();
        };
    };

    // Add a function to check if the error is related to browser installation issues
    const checkForBrowserInstallationIssues = (errorMessage) => {
        if (!errorMessage) return false;

        const lowerCaseError = errorMessage.toLowerCase();
        const isBrowserIssue =
            lowerCaseError.includes('browser not available') ||
            lowerCaseError.includes('failed to install browser') ||
            lowerCaseError.includes('executable doesn\'t exist') ||
            lowerCaseError.includes('webkit') ||
            lowerCaseError.includes('playwright');

        if (isBrowserIssue) {
            // Add a special status message with instructions
            addStatusMessage(
                'info',
                'To fix browser issues, run: ./install-webkit.sh (or "npx playwright install webkit")'
            );
        }

        return isBrowserIssue;
    };

    // Stop the browser stream with improved cleanup
    const stopStream = () => {
        if (eventSourceRef.current) {
            try {
                console.log('Stopping stream and cleaning up resources...');

                // First send a notification to the server that we're disconnecting
                // This helps the server clean up resources more gracefully
                try {
                    const socket = io.connect();
                    socket.emit('stream-disconnect', {
                        sessionId: sessionId || `stream-${Date.now()}`,
                        timestamp: Date.now()
                    });
                    // Disconnect the socket after sending the message
                    setTimeout(() => socket.disconnect(), 500);
                } catch (socketError) {
                    console.warn('Failed to notify server about stream disconnection:', socketError);
                }

                // Create a small delay before closing the connection to allow the server to process
                // This helps reduce "connection closed before message completed" errors
                setTimeout(() => {
                    // Close the EventSource connection
                    eventSourceRef.current.close();

                    // Remove all event listeners to prevent memory leaks
                    eventSourceRef.current.onmessage = null;
                    eventSourceRef.current.onerror = null;
                    eventSourceRef.current.onopen = null;

                    // Try to remove any custom event listeners
                    try {
                        eventSourceRef.current.removeEventListener('status', () => { });
                    } catch (listenerError) {
                        // Ignore errors from removing listeners
                        console.log('Minor error removing event listeners:', listenerError.message);
                    }

                    // Ensure the reference is cleared
                    eventSourceRef.current = null;

                    // Update UI state
                    setStreaming(false);
                    setStreamStatus('disconnected');
                    addStatusMessage('stream', 'Stream stopped and resources cleaned up');
                }, 100);
            } catch (error) {
                console.error('Error closing EventSource:', error);
                // Still clear the reference even if there was an error
                eventSourceRef.current = null;
                setStreaming(false);
                setStreamStatus('error');
            }
        }
    };

    // Scroll to bottom of messages
    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    const handleSendMessage = (inputValue) => {
        // Ensure we have a valid session
        if (!sessionId) {
            return addStatusMessage('error', 'No active session');
        }

        // Add user message optimistically
        const userMessage = { role: 'user', content: inputValue };
        setMessages(prevMessages => [...prevMessages, userMessage]);
        setInputValue('');
        setLoading(true);

        // Generate a unique message ID for tracking this request
        const messageId = Date.now().toString();

        // Set up failsafe timeout to prevent getting stuck in loading state
        const loadingTimeout = setTimeout(() => {
            if (loading) {
                console.warn('Loading state timeout reached - forcing reset');
                setLoading(false);
                addStatusMessage('warning', 'Request timed out. Try sending another message or reset the chat.');
            }
        }, 60000); // 1 minute timeout

        // Store the timeout ID for cleanup
        window._loadingTimeouts = window._loadingTimeouts || [];
        window._loadingTimeouts.push(loadingTimeout);

        // Determine endpoint based on the data being sent
        const endpoint = `/api/chat/${sessionId}`;

        // First, try sending through HTTP
        console.log(`Sending message to ${endpoint}`);
        axios.post(endpoint, { message: inputValue }, { timeout: 10000 }) // 10-second timeout
            .then(response => {
                clearLoadingTimeouts();
                console.log('Message sent successfully via HTTP');
                // This is handled by the streaming response or socket event
            })
            .catch(error => {
                clearLoadingTimeouts();
                console.error('Error sending message via HTTP:', error);

                // Check if this is a session error
                if (error.response && error.response.data && error.response.data.error === 'Session not found') {
                    addStatusMessage('error', 'Session expired. Please refresh the page.');
                    setLoading(false);
                    return;
                }

                // Handle connection errors specifically
                if (error.code === 'ECONNABORTED' || !error.response) {
                    addStatusMessage('error', 'Connection to server timed out. The server might be busy.');
                    setLoading(false);
                    return;
                }

                // Fallback for browser extension error
                if (error.message && error.message.includes('browser extension')) {
                    addStatusMessage('error', 'Browser extension is interfering with requests. Try disabling extensions.');
                    setLoading(false);
                    return;
                }

                // Generic error
                addStatusMessage('error', `Error: ${error.message}`);
                setLoading(false);
            });
    };

    // Function to clear all loading timeouts
    const clearLoadingTimeouts = () => {
        if (window._loadingTimeouts && window._loadingTimeouts.length > 0) {
            window._loadingTimeouts.forEach(timeout => clearTimeout(timeout));
            window._loadingTimeouts = [];
        }
    };

    // Add a function to request a screenshot
    const requestScreenshot = async () => {
        try {
            console.log("Requesting screenshot...");
            setError(null);
            const endpoint = '/api/screenshot';

            const response = await axios.get(endpoint);
            console.log("Screenshot requested successfully");
            return response; // Return the response for async/await
        } catch (err) {
            console.error("Error requesting screenshot:", err);
            setError("Failed to request screenshot: " + err.message);
            throw err; // Re-throw the error for async/await error handling
        }
    };

    const togglePreview = () => {
        setPreviewVisible(!previewVisible);

        // If hiding preview while streaming, stop the stream
        if (!previewVisible && streaming) {
            stopStream();
        }
    };

    // Helper to find the last message of a specific role
    const findLastMessage = (messages, role) => {
        for (let i = messages.length - 1; i >= 0; i--) {
            if (messages[i].role === role) return messages[i];
        }
        return null;
    };

    // Helper to find the last index of a message matching a condition
    const findLastIndex = (array, predicate) => {
        for (let i = array.length - 1; i >= 0; i--) {
            if (predicate(array[i])) return i;
        }
        return -1;
    };

    // Cleanup function
    useEffect(() => {
        return () => {
            // Cleanup function
            if (socket) {
                socket.disconnect();
            }

            // Clear all timeouts
            clearLoadingTimeouts();
        };
    }, []);

    // Reset chat functionality
    const resetChat = () => {
        console.log('Manually resetting chat state');

        // Stop any streaming in progress
        if (streaming) {
            stopStream();
        }

        // Clear loading state
        setLoading(false);

        // Clear all timeouts
        clearLoadingTimeouts();

        // Add a status message
        addStatusMessage('system', 'Chat reset by user');

        // Optional: clear messages or keep message history
        // setMessages([]); // Uncomment to clear all messages
    };

    return (
        <div className="App">
            <div className="chat-container">
                <div className="messages-container">
                    <div className="status-container">
                        {statusMessages.map((message, index) => (
                            <div
                                key={index}
                                className={`status-message ${message.type}`}
                            >
                                {message.text}
                            </div>
                        ))}
                    </div>

                    <div className="messages">
                        {messages.map((message, index) => (
                            <Message
                                key={index}
                                message={message}
                                isLoading={loading && index === messages.length - 1 && message.role === 'assistant'}
                            />
                        ))}
                        {loading && (!messages.length || messages[messages.length - 1]?.role !== 'assistant') && (
                            <Message message={{ role: 'assistant', content: 'Processing...' }} isLoading={true} />
                        )}
                    </div>
                </div>

                <div className="action-buttons">
                    <button
                        className="reset-button"
                        onClick={resetChat}
                        disabled={!sessionId}
                    >
                        Reset Chat
                    </button>
                    <button
                        className="check-server-button"
                        onClick={checkServerHealth}
                        disabled={!sessionId}
                    >
                        Check Server
                    </button>
                </div>

                <form className="input-container" onSubmit={(e) => { e.preventDefault(); handleSendMessage(inputValue); }}>
                    <input
                        type="text"
                        value={inputValue}
                        onChange={(e) => setInputValue(e.target.value)}
                        disabled={loading || !sessionId}
                        placeholder={sessionId ? "Type a message..." : "Initializing session..."}
                    />
                    <button type="submit" disabled={loading || !sessionId || !inputValue.trim()}>
                        Send
                    </button>
                </form>
            </div>
        </div>
    );
}

export default App;
